const runsOfCheck = `-- name: RunsOfCheck :many
SELECT id, workspace_id, check_id, rid, outcome, started_at, ended_at, timed_out_at, exit_status, measured, reason FROM runs WHERE check_id = ? AND id < ? ORDER BY id DESC LIMIT ?
`

type RunsOfCheckParams struct {
	CheckID string
	ID      string
	Limit   int64
}

func (q *Queries) RunsOfCheck(ctx context.Context, arg RunsOfCheckParams) ([]Run, error) {
	rows, err := q.db.QueryContext(ctx, runsOfCheck, arg.CheckID, arg.ID, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Run{}
	for rows.Next() {
		var i Run
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.CheckID,
			&i.Rid,
			&i.Outcome,
			&i.StartedAt,
			&i.EndedAt,
			&i.TimedOutAt,
			&i.ExitStatus,
			&i.Measured,
			&i.Reason,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const setAlerting = `-- name: SetAlerting :execrows
UPDATE checks SET urgency = ?, critical = ?, version = version + 1, updated_at = ?
WHERE workspace_id = ? AND id = ? AND deleted_at IS NULL
`

type SetAlertingParams struct {
	Urgency     string
	Critical    int64
	UpdatedAt   int64
	WorkspaceID string
	ID          string
}

func (q *Queries) SetAlerting(ctx context.Context, arg SetAlertingParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, setAlerting,
		arg.Urgency,
		arg.Critical,
		arg.UpdatedAt,
		arg.WorkspaceID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

